-- Isolated minimal schema matching the production catalog read on 2026-10-22.
do $$begin if not exists(select from pg_roles where rolname='anon') then create role anon;end if;if not exists(select from pg_roles where rolname='authenticated') then create role authenticated;end if;end$$;
create schema auth; create schema private;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table auth.users(id uuid primary key);
create table public.user_profiles(id uuid primary key,active boolean,role text,permissions text[] default array['borrow','prepare']::text[]);
create table public.audit_log(id bigint generated always as identity,actor_user_id uuid,table_name text,action text,row_id text,old_data jsonb,new_data jsonb,changed text[]);
create table public.assets(id bigint generated by default as identity primary key,no integer,type text default 'C2',status text default 'ใช้งานได้',updated_at timestamptz not null default now());
create table public.borrow_records(id bigint generated by default as identity primary key,record_date date not null,record_time time not null,shift text,action text not null,equipment_name text,equipment_number text,ward text,staff_name text,recorded_at timestamptz not null default now(),round_status text,note text,created_at timestamptz not null default now(),actor_user_id uuid default auth.uid() references auth.users);
create table public.prepare_records(id bigint generated by default as identity primary key,record_date date not null,record_time time not null,equipment_type text,equipment_number text,ward text,prepared_by text,recorded_at timestamptz not null default now(),status text not null default 'เตรียม',created_at timestamptz not null default now(),actor_user_id uuid default auth.uid() references auth.users);
create view public.equipment_status as select distinct on(equipment_name,equipment_number) equipment_name,equipment_number,ward,staff_name,action,recorded_at,action like '%ยืม%' or action like '%ย้าย%' or action like '%เปลี่ยน Circuit%' as is_borrowed from public.borrow_records where equipment_name is not null and equipment_number is not null order by equipment_name,equipment_number,recorded_at desc,id desc;
grant usage on schema public,auth,private to authenticated,anon;
grant select on public.assets,public.borrow_records,public.prepare_records,public.equipment_status to authenticated,anon;
grant insert,update,delete on public.borrow_records,public.prepare_records,public.assets to authenticated;
grant usage,select on all sequences in schema public to authenticated;

create function private.has_permission(page_key text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_profiles p where p.id=(select auth.uid()) and p.active and (p.role='admin' or page_key=any(p.permissions)))$$;
